+				return parseInt(restriction, 10) === 1 && setting.chatAllowList === undefined;
+			});
+			const following = await Promise.all(restricted.map(async (uid) => {
+				const [local, remote] = await Promise.all([
+					db.getSortedSetRange(`following:${uid}`, 0, -1),
+					db.getSortedSetRange(`followingRemote:${uid}`, 0, -1),
+				]);
+				return local.concat(remote);
+			}));
+			await db.setObjectBulk(restricted.map((uid, index) => [
+				`user:${uid}:settings`, {
+					chatAllowList: JSON.stringify(following[index].map(String)),
+					...(following[index].length ? {} : { disableIncomingMessages: 1 }),
+				},
+			]));
+			progress.incr(uids.length);
+		}, { batch: 500 });
+	},
+};
